INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('الروابط الهيدروجينية، مما يجعل الماء متماسكًا. ينشأ التوتر السطحي من قوة التماسك الناتجة عن التجاذب بين الجزيئات عند سطح السائل. ويمتلك الماء أيضًا خاصية أخرى، فهو مادة لاصقة لأنه قادر على الالتصاق بسطح أي جزيئات غير مائية قطبية أو مشحونة. الماء أكثر كثافة كسائل مما هو عليه في الحالة الصلبة (أي الجليد). تسمح هذه الخاصية الفريدة للمياه للجليد بالطفو فوق الماء السائل مثل البرك والبحيرات والمحيطات، وبالتالي عزل السائل الموجود بالأسفل عن الهواء البارد الموجود بالأعلى. يتمتع الماء بالقدرة على امتصاص الطاقة، مما يمنحه قدرة حرارية نوعية أعلى من المذيبات الأخرى مثل الإيثانول. وبالتالي، هناك حاجة إلى كمية كبيرة من الطاقة لكسر الروابط الهيدروجينية بين جزيئات الماء لتحويل الماء السائل إلى بخار ماء. كجزيء، الماء ليس مستقرًا تمامًا إذ يتفكك كل جزيء ماء بشكل مستمر إلى أيونات هيدروجين وهيدروكسيل قبل إعادة تشكيله إلى جزيء ماء مرة أخرى. في الماء النقي، عدد أيونات الهيدروجين يوازن (أو يساوي) عدد أيونات الهيدروكسيل، مما يؤدي إلى درجة حموضة محايدة. === المركبات العضوية === المركبات العضوية هي جزيئات تحتوي على الكربون المرتبط بعنصر آخر مثل الهيدروجين. باستثناء الماء، تحتوي جميع الجزيئات التي يتكون منها كل كائن حي تقريبًا على الكربون. يمكن للكربون أن يشكل روابط تساهمية مع ما يصل إلى أربع ذرات أخرى، مما يمكنه من تكوين جزيئات متنوعة وكبيرة ومعقدة. فمثلًا، يمكن لذرة كربون واحدة أن تشكل أربع روابط تساهمية مفردة مثل الميثان، أو رابطتين تساهميتين مزدوجتين مثل ثاني أكسيد الكربون (CO2)، أو رابطة تساهمية ثلاثية مثل في أول أكسيد الكربون (CO). ويمكن للكربون أن يشكل سلاسل طويلة جدًا من روابط الكربون والكربون المترابطة مثل الأوكتان أو الهياكل الشبيهة بالحلقة مثل الغلوكوز. أبسط شكل للجزيء العضوي هو الهيدروكربون، وهو عبارة عن عائلة كبيرة من المركبات العضوية التي تتكون من ذرات هيدروجين مرتبطة بسلسلة من ذرات الكربون. يمكن استبدال العمود الفقري الهيدروكربوني بعناصر أخرى مثل الأكسجين (O)، الهيدروجين (H)، الفوسفور (P)، والكبريت (S) مما يغير السلوك الكيميائي لذلك المركب. تسمى مجموعات الذرات التي تحتوي على هذه العناصر (O-، H-، P-، وS-) والمرتبطة بذرة كربون مركزية أو هيكل عظمي «المجموعات الوظيفية». يوجد ست مجموعات وظيفية بارزة في الكائنات الحية: المجموعة الأمينية، ومجموعة الكربوكسيل، ومجموعة الكربونيل، ومجموعة الهيدروكسيل، ومجموعة الفوسفات، ومجموعة السلفهيدريل. في عام 1953، أظهرت تجربة ميلر-يوري أنه من الممكن أن تتشكل المركبات العضوية بطريقة غير حيوية داخل نظام مغلق يحاكي ظروف الأرض المبكرة، مما يشير إلى أن الجزيئات العضوية المعقدة نشأت تلقائيًا في الأرض المبكرة. === الجزيئات الكبيرة === الجزيئات الكبيرة هي جزيئات تتكون من وحدات فرعية أو مونومرات أصغر. وتشمل المونومرات السكريات والأحماض الأمينية والنيوكليوتيدات. وتشمل الكربوهيدرات مونومرات وبوليمرات السكريات. الدهون هي الفئة الوحيدة من الجزيئات الكبيرة التي لا تتكون من البوليمرات. ويشمل ذلك المنشطات، والدهون الفوسفاتية، والدهون، وهي إلى حد كبير مواد غير قطبية وكارهة للماء (طاردة للماء). البروتينات هي الأكثر تنوعًا بين الجزيئات الكبيرة، وتشمل الإنزيمات، وبروتينات النقل، وجزيئات الإشارة الكبيرة، والأجسام المضادة، والبروتينات الهيكلية. الوحدة الأساسية (أو المونومر) للبروتين هي الحمض الأميني. تتركب كل البروتينات من عشرين حمضًا أمينيًا. الأحماض النووية هي بوليمرات من النيوكليوتيدات. وتتمثل مهمتها في تخزين المعلومات الوراثية ونقلها والتعبير عنها. == أسس علم الأحياء الحديث == === نظرية الخلية === تنصُّ نظرية الخلية على أنّ الخليَّة هي وحدة الحياة الأساسيَّة، وأنّ جميع الكائنات الحيَّة تتكون من خلية واحدة أو أكثر أو من مواد تُفرز من تلك الخلايا (مثل الهياكل الخارجية). تنشأ جميع الخلايا من خلايا أخرى بواسطة عملية الانقسام الخلوي، حيث يعود أصل كل خلية في جسم الكائن الحي متعدد الخلايا من خلية واحدة في البيضة المُخصبة. وكذلك تُعد الخليَّة الوحدة الأساسية في العديد من العمليات المرضيَّة. ويتمّ انتقال الطاقة في الخلايا بوساطة عمليات تُشكّل جُزءاً من عملية التمثيل الغذائي. وأخيراً فإنّ الخلايا تحتوي على المعلومات الوراثية (DNA) التي يتم تمريرها من خلية إلى أخرى أثناء انقسام الخلية. === التطور === التطور هو أحد مفاهيم علم الأحياء', 'Wikipedia Arabic - علم الأحياء', 'هذه هي أهم فروع علم الأحياء الأساسية: (part 3)', 'الأحياء', '[-0.0159912,0.020111