INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('الحديث، ويعني أنّ الحياة تتغير وتتطور، وأنّ أشكال الحياة المعروفة كافة تنحدر من سلف مشترك. حيث تفترض نظرية التطور أنّ جميع الكائنات الحيَّة على وجه الأرض سواءً كانت حيَّةً أو مُنقرضةً قد انحدرت من أصل مُشترك أو تجميعة جينية أولية. يُعتقد أنّ آخر سلف مُشترك لجميع الكائنات الحيَّة كان قد ظهر قبل حوالي 3.5 مليار عام. ويرى العلماء الداعمون لهذه النظرية أنّ تشارك الكائنات الحيَّة في الشفرة الجينية يُشكّل دليلاً حاسماً لصالح نظريتهم، بينما يرى المُعارضون لها عدم صحة العبارة وبالتالي فإنها لا تُشكل دليلاً داعماً للتطور. أُدخل مُصطلح التطور إلى المعجم العلمي بوساطة العالم الفرنسي جان باتيست لامارك عام 1809، أما البداية الفعلية للنظرية فكانت على يد تشارلز داروين بعد ذلك بخمسين عاماً لتُصبح نموذجاً علمياً فعلياً، ويُعزى ذلك إلى توضيحه القوة أو الآلية الدافعة للتطور، وهي الانتقاء الطبيعي (كما يُعد ألفرد راسل والاس مُساهماً في اكتشاف هذا المفهوم، بالإضافة إلى مُساهمته بالأبحاث والتجارب المُتعلقة بالتطور). قال داروين في نظريته إنّ الأنواع والسلالات تتطور خلال عمليات الانتقاء الطبيعي والانتقاء الاصطناعي، بالإضافة إلى الانحراف الوراثي الذي شكّل آليةً تطوريةً أخرى في توليفة النظرية الحديثة. يُطلق اسم علم الوراثة العرقي على التاريخ التطوري للأنواع الذي يصف خصائص الأنواع المُختلفة من الأصل الذي انحدرت منه، بالإضافة إلى علاقة النَّسب بين النوع والأنواع الأخرى. هناك العديد من الوسائل المُستخدمة في توليد المعلومات حول علم الوراثة العرقي. إحدى هذه الوسائل هي مُقارنة تسلسلات الدي إن إيه التي تتبع مجال علم الأحياء الجزيئي أو علم الجينوم. وسيلةٌ أخرى هي مُقارنة المستحاثات أو ما نملك من معلومات عن الكائنات القديمة في علم الأحياء القديمة. === علم الوراثة === الجين هو الوحدة الأساسية للوراثة في جميع الكائنات الحيَّة ويُشكّل المنطقة التي تؤثر على شكل أو وظيفة الكائن الحي من المادة الوراثية. حيث أنّ جميع الكائنات الحيَّة من البكتيريا إلى الحيوانات تتشارك في نفس الآليات الأساسية المُتمثلة في نسخ وترجمة الدنا إلى بروتينات. تقوم الخلايا بنسخ جين الدنا إلى جين الرنا ثم يترجم الرايبوسوم الرنا إلى بروتين، وهو عبارةٌ عن سلسلة من الأحماض الأمينية. تتشارك مُعظم الكائنات الحيَّة في رمز الترجمة من الرنا إلى الأحماض الأمينية، ولكنها قد تكون مُختلفةً قليلاً في بعضها الآخر. تكون الكروموسومات عادةً خطية الشكل في حقيقيات النوى ودائرية الشكل في بدائيات النوى. والكروموسوم هو تركيبٌ مُنظمٌ يتألف من الدنا والهستونات. وتُشكّل مجموعة الكرموسومات الموجودة في الخلية، بالإضافة إلى أية معلومات وراثية أخرى موجودة في الميتوكوندريا والبلاستيدات الخضراء أو أي مكان آخر، تُشكل مُجتمعةً ما يُعرف باسم الجينوم. توجد المعلومات الوراثية في حقيقيات النوى في نواة الخلية، بالإضافة إلى كميات أخرى صغيرة موجودة في الميتوكندريا والبلاستيدات الخضراء. أما في بدائيات النوى فتكون المادة الوراثية موجودةً في جسم غير مُنتظم الشكل يقع في السيتوبلازم يُسمّى بالنيوكليود. تكون معلومات الجينوم الوراثية موجودةً في الجينات، ويُسمّى مجموع هذه المعلومات في الكائن الحي بالنمط الجيني. === الاستتباب === الاستتباب هو قدرةُ النظام المفتوح على تنظيم بيئته الداخلية للحفاظ على ظروف مُستقرة عن طريق تحقيق توازن ديناميكي. وهو خاصيةٌ تظهر في جميع الكائنات الحيَّة سواءً كانت وحيدة الخلية أو مُتعددة الخلايا. يجب على النظام أن يكون قادراً على الكشف عن الاضطرابات والرد عليها بشكل مُناسب للحفاظ على توازنه الديناميكي وأداء وظائفه بشكل فعّال. حيث يقوم النظام الحيوي عادةً بالاستجابة على الاضطرابات بعد كشفها من خلال الارتجاع السلبي، ممّا يُتيح له القدرة على الحفاظ على ظروف مُستقرة من خلال تخفيض أو زيادة نشاط أحد الأعضاء أو الأجهزة. ومن الأمثلة على ذلك انخفاض الغلوكاغون عندما تكون مُستويات السكر مُنخفضةً جداً. === الطاقة === يعتمد بقاء الكائن الحي على استمرار إمداده بالطاقة. ويتم الحصول على هذه الطاقة من المواد التي تُشكّل غذاء بوساطة تفاعلات كيميائية، وتُستغل هذه الطاقة في المُساعدة في تشكيل خلايا جديدة والمُحافظة عليها. تلعب جُزيئات المواد الكيميائية التي تُشكل غذاء الكائن الحي دورين خلال هذه العملية: الأول أنها تُشكل مصدراً للطاقة التي يحتاجها الجسم، والثاني هو تكوين تراكيب جزيئية', 'Wikipedia Arabic - علم الأحياء', 'هذه هي أهم فروع علم الأحياء الأساسية: (part 4)', 'الأحياء', '[0.0288696,0.0566406,0.0314331,0.0264435,0.0475769,0.0335083,0.0349