INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('تتألف من جزيئات حيويَّة. تُعرف الكائنات الحيَّة التي تقوم بإنتاج الطاقة في النظام البيئي بالكائنات المُنتجة أو ذاتية التغذية. تُشكل الشمس مصدر الطاقة الأساسي لجميع الكائنات ذاتية التغذية تقريباً، حيث تستخدم الطاقة الشمسية في عملية تُعرف بعملية البناء الضوئي لتحويل المواد الخام إلى جزيئات عضوية مثل ثلاثي فوسفات الأدينوسين (ATP) يُمكن تحطيم روابطها لإطلاق الطاقة. بَيْد أنّ بعض الكائنات تعتمد كلياً على مصادر أخرى للطاقة غير الشمس مثل الميثان وأيونات الكبريت. تُستغل بعض الطاقة في إنتاج الكتلة الحيوية لاستمرار الحياة وتوفير القدرة على النمو، بَيْد أنّ مُعظم الطاقة المُتبقيَّة تُفقد على شكل حرارة أو فضلات جُزيئية. أهم عمليات تحويل الطاقة الموجودة في المواد الكيميائية إلى طاقة مُفيدة للكائن الحي هي عملية التمثيل الضوئي وكذلك التنفس الخلوي. == الدراسات والبحوث == === التركيبية === يختص علم الأحياء الجزيئي بدراسة الأحياء على المُستوى الجُزيئي، ويتداخل هذا الفرع مع فروع أحيائيَّة أخرى، خصوصاً مع علم الوراثة والكيمياء الحيوية. تهتم الأحياء الجزيئية بصورة رئيسية بالتفاعلات بين النظم المُختلفة في الخلية، بما في ذلك العلاقات المُتبادلة بين الدنا والرنا ومعرفة كيف يتم تنظيم هذه التفاعلات. يدرس علم الأحياء الخلوي الخصائص التركيبية والفسيولوجية للخلايا، بما في ذلك سلوكها وتفاعلاتها وبيئتها. تتم هذه الدراسة على الصعيدين المجهري والجزيئي في الكائنات وحيدة الخلية مثل البكتيريا، وكذلك في الخلايا المُتخصصة في الكائنات عديدة الخلايا مثل البشر. فهم بنية ووظيفة الخلايا هو أمرٌ أساسيٌّ في جميع العلوم الأحيائيَّة، ويهتم علم الأحياء الجزيئي بشكل خاص في أوجه الشَّبه والاختلاف بين أنواع الخلايا. بينما يهتم علم التشريح بدراسة التراكيب على مستوى أكبر مثل الأعضاء والأجهزة. يدرس علم الوراثة الجينات والتوريث والتنوّع في الكائنات الحيَّة. تقوم الجينات بفك تشفير المعلومات اللازمة لتصنيع البروتينات، التي بدورها تلعب دوراً محورياً في التأثير على النمط الظاهري النهائي للكائن الحي. يوفر علم الوراثة الحديث أدواتٍ مُهمةٍ لمعرفة وظيفة جين مُعيَّن. تُحمل المعلومات الوراثية بشكل عام على الكروموسومات، حيث يتم تمثيلها في التركيب الكيميائي لجزيئات دنا مُعيَّنة. يختص علم الأحياء التطوري بدراسة عملية نمو الكائنات الحيَّة وتطورها. تدرس الأحياء التطورية الحديثة التحكم الجيني في تكاثر الخلايا، والتمايز الخلوي، و«التخلق»، وهي العملية التي تؤدي تدريجياً إلى نشوء الأنسجة والأعضاء. ومن المُصطلحات المُتعلقة بالأحياء التطورية هو النموذج الحي الذي يُشير إلى الأنواع التي يتم دراستها بشكل مُكثف بغرض فهم ظاهرة بيولوجية مُعيَّنة، أي مُحاولة تعميم المعلومات المُكتشفة عن الكائن القابع تحت الدراسة على الكائنات الأخرى. ومن هذه النماذج الحيَّة الربداء الرشيقة، وسمكة زيبرا، وفأر المنازل، وغيرها. === الوظيفة === يدرس علم وظائف الأعضاء العمليات الميكانيكية والفيزيائية والكيميائية الحيوية للكائنات الحيَّة من خلال مُحاولة فهم كيفيَّة عمل تراكيب الجسم المُختلفة. تُقسم الدراسات المُتعلقة بهذا الفرع عادةً إلى فرعين ثانويين يختص أحدهما بالنباتات والآخر بالحيوانات، لكنّ بعض مبادئه تكون مُشتركةً بين جميع الكائنات الحيَّة. فما يدرسه علم وظائف الأعضاء على خلايا الخميرة مثلاً ينطبق أيضاً على الخلايا البشريَّة. تستمد الدراسات التي تجري على الحيوانات في هذا المجال أدواتها وأساليبها من تلك التي تُجرى على البشر، بينما تستمد الدراسات المُجرية على النباتات أساليبها من كلا المجاليْن السابقيْن. يدرس علم وظائف الأعضاء على سبيل المثال كيفيَّة عمل الجهاز العصبي، والمناعي، والغدد الصماء، والتنفسي، والدوراني وترابطها مع بعضها البعض. يتشارك علم وظائف الأعضاء في دراسته لأجهزة الجسم مع فروع أخرى ذات علاقة بالطب مثل علم الأعصاب وعلم المناعة. === التطورية === تهتم الدراسات التطورية بأصول الأنواع، بالإضافة إلى تغيُّرها عبر الزمن، ويقوم بهذه الدراسات علماء من فروع أحيائيَّة تصنيفيَّة مُختلفة. حيث يكون لدى هؤلاء العلماء عادةً خبرةٌ في كائنات مُعيَّنة، مثل المُختصين في علم الثدييات وعلم الطيور، وعلم النبات، وعلم الزواحف والبرمائيات، لكنهم يستخدمون معرفتهم لهذه الكائنات في الإجابة على الأسئلة العامة حول التطور. ترتكز الأحياء التطورية جُزئياً على علم الأحياء القديمة الذي يستخدم سجلات الأحافير للإجابة على الأسئلة المُتعلقة بوضع التطور ووتيرته، وكذلك على التطورات الحاصلة في المناطق مثل الوراثيات السكانية. كما أنّ هناك فروع أخرى ذات علاقة بالأحياء التطورية مثل علم الوراثة العرقي،', 'Wikipedia Arabic - علم الأحياء', 'هذه هي أهم فروع علم الأحياء الأساسية: (part 5)', 'الأحياء', '[0.0271606,0.0389709,0.1000366,-0.0055695,0.0202179,0.0228577,0.0167236,0.0446472,-0.0064087,0.0137329,-0.0016413,-0.0143738,-0.0317993,0.0066719,-0.0177765,0.0516968,-0.0002995,0.0180511,0.0279694,0.0195465,0.0806885,-0.0509338,0.0447693,-0.0108337,-0.0272369,-0.0374451,-0.0178070,0.0469971,0.0017719,0.0213928,0.0388184,-0.0022640,-0.0287323,0.0250092,-0.0542297,0.0595093,-0.0212402,0.0087509,0.0175323,-0.0118561,0.0163269,-0.0220184,-0.0859375,0.0057106,-0.0319824,0.0236053,-0.0352478,0.0167999,-0.0104980,0.0242767,0.0171051,-0.0200195,0.0543823,-0.0251007,-0.0200195,0.0606689,0.0055161,-0.0220184,-0.0117264,-0.0033016,0.0202789,0.0302277,0.0372314,0.0012398,-0.0054436,0.0129089,0.0121078,0.0141678,-0.0501404,-0.0078049,0.0579224,-0.0121231,-0.0264587,0.0595093,0.0288849,0.0112686,0.0580444,-0.0017414,-0.0143585,0.0474548,0.0225677,-0.0233307,-0.0057564,-0.0186920,0.0183105,-0.0029564,-0.0339050,-0.0578308,-0.0502930,0.0065498,-0.0466309,0.0514221,-0.0268860,0.0007815,0.0070152,-0.0207062,-0.0195923,-0.0649414,0.0249786,0.0118942,-0.0014353,-0.0055809,-0.0173187,-0.0021992,0.0028172,-0.0731201,-0.0503540,-0.0116425,-0.0535889,-0.0163727,-0.0359192,-0.0318604,0.0382080,0.0007572,0.0484314,-0.0380249,-0.0231171,0.0148087,0.0057793,-0.0084991,0.0024338,-0.0191650,0.0018301,-0.0120239,0.0247040,-0.0501099,0.0070229,0.0559692,-0.0252380,0.0226898,-0.0108414,-0.0118790,-0.0253448,-0.0355530,-0.0289612,-0.0307617,0.0274200,0.0354919,0.0102692,0.0217590,0.0313416,0.0125656,0.0046768,0.0392761,0.0243835,-0.0167084,0.0372925,0.0420227,-0.0217285,0.0923462,0.0096207,-0.0016165,-0.0472717,0.0132294,0.0155563,0.0274048,-0.0445862,0.0422058,-0.0174408,-0.0106277,0.0147552,0.0090942,-0.0014353,0.0316467,-0.0695801,0.0098114,-0.0361328,0.0823975,-0.0265503,0.0494995,-0.0501099,-0.0377502,0.0454407,0.0342102,-0.0033493,-0.0184021,-0.0048790,-0.05236