INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('وعلم النظاميات الحيوية، وعلم التصنيف. === التنظيمية === يؤدي حدوث ما يُعرف بالانتواع إلى تكوين شجرة من العلاقات بين الأنواع. يتمثل دور النظاميات في دراسة هذه العلاقات من حيث الاختلافات والتشابهات فيما بينها، علماً بأنّ النظاميات كانت مجالاً خصباً للدراسات قبل فترة طويلة من نشوء الفكر التطوري. عادةً ما يتم تقسيم الكائنات الحيَّة إلى خمس ممالك: البدائيات، والطلائعيات، والفطريات، والنباتات، والحيوانات. بَيْد أنّ العديد من العلماء باتوا ينظرون إلى هذا التقسيم على أنّه تقسيمٌ عفا عليه الزمن. أمّا التصانيف البديلة الحديثة فإنها غالباً ما تبتدئ بثلاثة نطاقات: العتائق، والبكتيريا، وحقيقيات النوى (التي تشمل الطلائعيات والفطريات والنباتات والحيوانات). تُعبر هذه النطاقات عن امتلاك الخلايا للأنوية من عدمه، بالإضافة إلى الاختلافات في التركيب الكيميائي للجزيئات الحيوية الأساسية مثل الريبوسومات. وعلاوةً على ذلك تُقسم كل مملكة إلى أقسام تُقسم بدورها إلى أقسام أخرى بترتيبٍ مُعيَّن حتى يتم تصنيف كل نوع على حدة. والترتيب هو: نطاق، مملكة، شعبة، طائفة، رتبة، فصيلة، جنس، نوع. وبالإضافة إلى هذه الفئات فإنّ هناك الطفيليات إجبارية الوجود داخل الخلايا التي تُصنف على أنها «على حافة الحياة» من حيث النشاط الأيضي، أي أنّ العديد من العلماء لا يصنفونها على أنها كائنات حيَّة نظراً لافتقارها لواحدة أو أكثر من الوظائف الأساسية أو الخصائص التي يتميز بها أي كائن حي. تُقسم هذه الطفيليات إلى فيروسات، وأشباه فيروسات، وبريونات، وتوابع. === البيئية === يدرس علم البيئة توزيع ووفرة الكائنات الحيَّة، وتفاعل هذه الكائنات مع بيئتها. يُمكن اعتبار موطن الكائن الحي على أنه العوامل اللاحيوية المحلية مثل المناخ، بالإضافة إلى الكائنات الحيَّة الأخرى والعوامل الحيوية التي تُشاركه بيئته. يصعب دراسة هذه الأنظمة البيولوجية بسبب التباين الكبير في التفاعلات التي يُمكن أن تُجرى بين الكائنات الحيَّة المُختلفة، وحتى الكائنات الدقيقة. فالبكتيريا المجهرية على سبيل المثال تستجيب لبيئتها بقدر ما يستجيب الأسد الباحث عن طعامه في السافانا الأفريقية. يختلف سلوك الكائنات الحيَّة من حالةٍ إلى أخرى، فقد يكون سلوكاً تعاونياً أو تنافسياً أو تطفلياً أو تعايشياً. وتصبح الأمور أكثر تعقيداً عندما يتفاعل نوعين أو أكثر في نظام بيئي. يُدرس علم البيئة على مُستويات عديدة مُختلفة، من الأفراد إلى الجماعات إلى الأنظمة البيئية والغلاف الحيوي. يُستخدم مُصطلح علم الأحياء التجمعي عادةً لنفس الدلالة التي يُشير إليها علم البيئة التجمعي، بَيْد أنّ علم الأحياء التجمعي أكثر استخداماً عندما يكون مجال الدراسة مُتعلقاً بالأمراض، أو الفيروسات، أو الميكروبات، في حين أنّ علم البيئة التجمعي أكثر شيوعاً عندما تكون النباتات والحيوانات محور الدراسة. ويندرج تحت علم البيئة العديد من التخصصات الفرعية. تدرس الإيثولوجيا أو علم السلوك الحيواني سلوك الحيوانات المُختلفة (لا سيما الحيوانات الاجتماعية مثل الرئيسيات والكلبيات)، ويُعد في بعض الأحيان فرعاً من فروع علم الحيوان. يهتم علماء السلوك الحيواني بوجه خاص بتطور السلوك ومفهوم السلوك من وجهة نظر نظرية الانتقاء الطبيعي. أي أنّ تشارلز داروين بطريقة أو بأخرى كان أول عالم سلوك حيواني، حيث ألهم كتابه «التعبير عن العواطف عند الإنسان والحيوانات» العديد من علماء السلوك الحيواني فيما بعد. أما علم الجغرافيا الحيوية فيدرس التوزيع المكاني للكائنات الحيَّة على الأرض مُتضمناً في دراسته العديد من المواضيع مثل الصفائح التكتونية، وتغير المناخ، وهجرة الحيوانات. == فروع علم الأحياء == هذه هي أهم فروع علم الأحياء الأساسية: علم الزراعة الذي يدرس إنتاج المحاصيل الزراعية وتربية المواشي، مع التركيز على التطبيقات العملية. علم التشريح الذي يدرس الشكل والوظيفة في الكائنات الحيَّة سواءً كانت نباتات أو حيوانات، ويدرس البشر على وجه التحديد. علم الأنسجة الذي يدرس الخلايا والأنسجة، وهو فرع مجهري لعلم التشريح. علم الأحياء الفلكي الذي يدرس التطور والتوزيع ومُستقبل الحياة على الكون. الكيمياء الحيوية التي تدرس التفاعلات الكيميائية اللازمة لنشوء الحياة وبقائها واستمرارها، وعادةً ما يكون التركيز على المُستوى الخلوي. الهندسة الحيوية، وهي دراسة الأحياء بوسائل هندسية مع التركيز على المعرفة التطبيقية وخصوصاً تلك المُتعلقة بالتكنولوجيا الحيوية. الجغرافيا الحيوية، وهي دراسة توزيع الأنواع مكانياً وزمانياً. المعلوماتية الحيوية المُتمثلة في استخدام تكنولوجيا المعلومات لدراسة وجمع وتخزين البيانات الجينومية وغيرها من البيانات البيولوجية.', 'Wikipedia Arabic - علم الأحياء', 'هذه هي أهم فروع علم الأحياء الأساسية: (part 6)', 'الأحياء', '[0.0128021,0.0286102,0.0598145,0.0103073,0.0214233,0.0441589,-0.0102158,0.0404358,-0.0283356,0.0443420,0.0117188,-0.0055733,-0.0015688,-0.0112457,0.0181122,0.0403137,-0.0030136,0.0545654,0.0193939,0.0125885,0.0830078,-0.0336304,0.0276337,-0.0010233,-0.0131073,-0.0505981,0.0026550,0.0736694,0.0017815,0.0262909,0.0453796,-0.0150604,-0.0086212,0.0035305,0.0040283,0.0144196,-0.0141983,-0.0190582,0.0015507,0.0145645,0.0188904,-0.0252380,-0.0558167,-0.0226135,-0.0271912,0.0341492,-0.0512695,0.0166626,0.0224762,0.0160217,-0.0170441,-0.0084457,0.0560303,-0.0228882,0.0166779,0.0419006,0.0091705,-0.0087128,-0.0038548,-0.0269012,0.0287323,0.0297241,0.0459900,0.0213776,-0.0251923,0.0038929,0.0042648,-0.0116348,-0.0399475,-0.0476685,0.0387878,-0.0065613,-0.0379944,0.0337219,-0.0025845,0.0056496,0.0348816,0.0318298,-0.0280151,0.0039711,-0.0122070,-0.0140533,-0.0037251,-0.0031013,-0.0203094,0.0096436,-0.0555725,-0.0375977,-0.0480652,0.0077972,-0.0156708,0.0099258,-0.0471497,0.0072136,0.0191650,-0.0111542,-0.0152817,-0.1110229,-0.0128403,-0.0084610,-0.0083542,-0.0305786,-0.0528259,-0.0229797,-0.0098267,-0.0497131,-0.0238647,0.0055504,-0.0416260,-0.0459595,-0.0182190,-0.0346069,0.0133286,-0.0084076,0.0327759,-0.0357666,-0.0163574,-0.0176849,0.0417175,-0.0123978,0.0059776,-0.0079498,0.0116882,-0.0118332,0.0195465,-0.0189209,-0.0023403,0.0455322,0.0149231,0.0139847,-0.0036221,0.0051918,0.0063438,-0.0255280,-0.0153275,-0.0149231,0.0040855,0.0008459,-0.0152664,0.0386047,0.0222626,0.0026550,0.0258331,0.0476379,-0.0215149,-0.0631714,0.0101242,0.0218811,-0.0150833,0.0996094,-0.0092468,0.0086441,-0.0733643,0.0151443,0.0225830,-0.0147552,-0.0311279,0.0211945,-0.0006995,0.0143738,0.0517273,-0.0241394,0.0308228,0.0057259,-0.0314941,0.0055923,-0.0667725,0.0635376,-0.0241699,0.0523987,-0.0358582,-0.0016508,0.0568542,0.0012312,-0.0199890,0.0268402,-0.0136948,-0.0346985,-0.0070419,-0.0230103,-0.0213013,0.0121