INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('علم الأحياء الرياضي، وهو الدراسة الكمية أو الرياضية للعمليات البيولوجية، مع التركيز على النمذجة. الميكانيكا الحيوية، غالباً ما تُعد فرعاً من فروع الطب، وهي دراسة ميكانيكا الكائنات الحيَّة مع التركيز على الاستخدامات التطبيقية. علم الصيدلة، وهو دراسة تحضير واستخدام وآثار العقاقير والأدوية الصناعية. الفيزياء الحيوية، وهي دراسة العمليات البيولوجية من وجهة نظر فيزيائية من خلال تطبيق النظريات والأساليب المُستخدمة في العلوم الفيزيائية. التقانة الحيوية، وهي تطبيق المعلومات المتعلقة بالمنظومات الحية بهدف استعمال هذه المنظومات أو مكوناتها في الأغراض الصناعية. علم النبات الذي يختص بدراسة النباتات بمُختلف أنواعها. علم الأحياء الخلوي الذي يدرس الخلية كوحدة كاملة، وكذلك يدرس التفاعلات الجزيئية والكيميائية التي تحدث داخل الخلية الحيَّة. علم حفظ الأحياء الذي يدرس كيفية حفظ وحماية واستعادة البيئة الطبيعية، والأنظمة البيئية الطبيعية، والغطاء النباتي، والحياة البرية. علم الحياة التقريسي، وهو العلم الذي يدرس تأثير درجات الحرارة المُنخفضة على الكائنات الحيَّة. علم الأحياء النمائي، وهو العلم الذي يختص بدراسة العملية التي ينمو ويتشكل ويتطور بها الكائن الحي في مراحل نموه. علم الأجنة الذي يدرس مراحل نمو الجنين مُنذ الإخصاب وحتى الولادة. علم البيئة، وهو العلم الذي يدرس تفاعلات الكائنات الحيَّة مع بعضها البعض ومع العناصر غير الحيَّة في بيئتها. علم البيئة التجمعي الذي يدرس تحركات تجمعات الأنواع وكيفية تفاعل هذه التجمعات مع بيئتها. علم الوبائيات الذي يُشكل عنصراً رئيسياً في مجال البحوث الصحية العامة، حيث يدرس العوامل التي تؤثر على صحة السكان. علم الأحياء التطوري الذي يدرس أصل الأنواع على مر الزمن.', 'Wikipedia Arabic - علم الأحياء', 'هذه هي أهم فروع علم الأحياء الأساسية: (part 7)', 'الأحياء', '[0.0136566,0.0252075,0.0740356,0.0218048,0.0015764,0.0291443,0.0386047,0.0240021,-0.0296783,-0.0033607,0.0006394,0.0120316,-0.0226288,0.0065155,0.0294037,0.0173492,0.0001540,0.0182190,0.0116043,-0.0200500,0.1210327,-0.0383606,0.0395813,-0.0281830,0.0120392,-0.0607605,0.0038033,0.0717163,0.0216980,0.0193024,0.046508