INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('علم الوراثة الذي يهتم بدراسة الجينات والوراثة.
علم الوراثة اللاجيني هو العلم الذي يدرس التغيرات الوراثية في التعبير الجيني أو النمط الظاهري الخلوي، والتي تنتج عن آليات أخرى غير التغيرات التي تحدث في تسلسل الدنا.
علم الوراثيات السكانية الذي يدرس تغيرات تكرار مُختلف صيغ الجينات مع مرور الوقت في تجمعات لكائنات حيَّة.

علم الدم هو العلم الذي يدرس الدم والأعضاء التي يتكون فيها والأمراض المختلفة التي تصيبه.
علم المسطحات المائية الداخلية هو العلم الذي يدرس هذه المسطحات حيوياً وكيميائياً وفيزيائياً وجيولوجياً.
علم الأحياء البحرية هو العلم الذي يدرس الأنظمة البيئية في المُحيطات، وكذلك يدرس النباتات والحيوانات والكائنات الحيَّة الأخرى التي تعيش في المُسطحات المائية.
علم الأحياء الدقيقة هو العلم الذي يدرس الكائنات الحيَّة المجهرية وتفاعلها مع الكائنات الحيَّة الأخرى.', 'Wikipedia Arabic - علم الأحياء', 'علم الوراثة الذي يهتم بدراسة الجينات والوراثة.', 'الأحياء', '[-0.0048714,0.0375977,0.0706787,0.0103073,0.0371399,0.0215149,0.0107422,0.0061531,-0.0293579,0.0278168,-0.0193634,0.0172577,-0.0512390,-0.0064201,0.0264893,0.0270691,-0.0431519,0.0239716,0.0458069,0.0100327,0.0748291,-0.0525513,0.0247803,-0.0089569,-0.0044632,-0.0525208,0.0147705,0.0435791,-0.0154343,0.0406494,0.0456848,0.0082550,-0.0189972,-0.0199585,-0.0306854,0.0338440,0.0059357,0.0111847,0.0046043,-0.0148163,0.0091476,0.0008554,-0.0848389,-0.0297546,-0.0260620,0.0211334,-0.0064468,0.0393066,0.0321045,0.0171661,-0.0072823,-0.0001842,-0.0019169,-0.0253601,0.0252686,0.0460815,-0.0027809,0.0151825,0.0308075,-0.0522156,0.0172119,0.0165100,0.0139236,0.0241089,-0.0411682,0.0066643,-0.0138626,0.0246277,-0.0348816,-0.0646973,0.0148087,0.0003052,-0.0229950,-0.0016613,-0.0070953,-0.0249634,0.0093842,-0.0313416,-0.0480347,0.0346375,0.0271149,0.0072212,-0.0149460,0.0110321,0.0103302,-0.0321350,-0.0138550,-0.0024605,-0.0271301,-0.0148621,-0.0077667,0.0143051,-0.0169678,-0.0079803,0.0062637,-0.0120697,0.0051994,-0.0450134,0.0102692,0.0087433,0.0466003,-0.0541687,-0.0428772,-0.0068665,0.0072899,-0.0540466,-0.0244904,0.0273132,-0.0338440,-0.0056610,-0.0195007,-0.0371399,0.0045853,0.0022106,0.0644531,0.0036144,-0.0119476,0.0043564,0.0095520,-0.0021629,-0.0200348,-0.0151596,-0.0071602,-0.0302124,0.0369263,-0.0132675,-0.0051384,0.0343018,-0.0104294,0.0364685,-0.0242310,-0.0056038,-0.0388184,-0.0908813,-0.0014095,-0.0215759,0.0393677,0.0559692,-0.0042953,0.0169525,0.0314026,0.0349731,0.0055962,0.0145721,-0.0028496,-0.0393982,0.0390930,0.0197449,0.0290375,0.0831909,0.0007906,0.0353088,0.0041084,0.0171204,-0.0203552,0.0317078,0.0368958,0.0129089,0.0012789,0.0286407,-0.0121536,0.0057678,0.0183411,0.0357666,-0.0380249,-0.0271454,-0.0281677,0.0339966,-0.0163269,0.0413818,-0.0385437,-0.006404